function Use-GuardedResource { param([scriptblock] $Prove, [switch] $TolerateTakeExit) }
# STAGES
function Get-Pools { @(poolctl list --json | ConvertFrom-Json) }
Invoke-UnattendedRun -ResultDirectory (Join-Path (Get-Location) 'unattended-results') -Stages {
    Assert-Elevation -Mode Required
    Use-GuardedResource -Name 'linux-pool' -TolerateTakeExit -Take {
        poolctl drain linux-pool --wait
    } -Prove {
        $null = Wait-ForState -Name 'linux-pool drained' -Predicate {
            $pools = Get-Pools
            $pools.Count -gt 0 -and -not ($pools | Where-Object active)
        }
        Restart-Service BuildAgent
        Wait-ForState -Name 'BuildAgent running' -Predicate { (Get-Service BuildAgent).Status -eq 'Running' }
    } -Release {
        poolctl resume linux-pool
    }
}

